//! 🛂️ Changed own Part21 arguments use the schema-neutral borrowed declaration authority.
use super::*;
use super::domain::{DomainControl,ValueChange};
pub(super)fn path(event:&SnapshotEditEvent)->Option<(&str,ValueChange)>{match event{SnapshotEditEvent::SetValue{path,..}=>Some((path,ValueChange::Set)),SnapshotEditEvent::InsertValue{path,..}=>Some((path,ValueChange::Insert)),SnapshotEditEvent::RemoveValue{path}=>Some((path,ValueChange::Remove)),SnapshotEditEvent::MoveValue{path,..}=>Some((path,ValueChange::Move)),_=>None}}
pub(super)fn draft(event:&SnapshotEditEvent)->bool{let SnapshotEditEvent::SetValue{path,value}=event else{return false};let fields:Vec<_>=path.split('/').skip(1).collect();fields.len()>=5&&fields[0]=="document"&&fields[1]=="instances"&&fields[3]=="entities"&&(fields.len()==6&&fields[5]=="typeName"||fields.len()==5&&requested_type(value).is_some())}
pub(super)fn route(before:&V,suffix:&str,indices:&mut[usize;128])->Result<usize,String>{let mut fields=suffix.split('/').skip(1).peekable();let mut value=before;let mut length=0;while let Some(field)=fields.next(){if field=="value"||field=="typeName"{return Ok(length);}if field!="values"{return Err("ifc-domain-path".into());}if fields.peek().is_none(){return Ok(length);}let items=match value{V::List(items)|V::Typed{items,..}=>items,_=>return Err("ifc-domain-path".into())};let field=fields.next().unwrap();let index=if field=="-"{items.len()}else{field.parse::<usize>().map_err(|_|"ifc-domain-path")?};if length==indices.len(){return Err("ifc-domain-depth".into());}indices[length]=index;length+=1;if fields.peek().is_none(){return Ok(length);}value=items.get(index).ok_or_else(||"ifc-domain-path".to_owned())?;}Ok(length)}
/// 🛂️ Validate prepared own instance mutations against the original captured Part21 arguments.
pub(super)fn check(event:&SnapshotEditEvent,snapshot:&Ifc2x3Snapshot,mutations:&[Ifc2x3Mutation],tick:&mut dyn FnMut()->Result<(),String>)->Result<(),Fault>{
 tick().map_err(err)?;if draft(event){return Ok(());}let Some((path,operation))=path(event)else{return Ok(())};let mut fields=path.split('/').skip(1);if fields.next()!=Some("document")||fields.next()!=Some("instances"){return Ok(());}let Some(row)=fields.next().and_then(|row|row.parse::<usize>().ok())else{return Ok(())};let Some(before)=snapshot.document.instances.get(row)else{return Ok(())};
 for mutation in mutations{tick().map_err(err)?;let Ifc2x3Mutation::UpsertInstance(change)=mutation else{continue};let after=&change.instance;if before.entities.len()!=after.entities.len(){return Err(err("ifc-domain-complex-draft-required"));}for(part,((old_name,prior),(name,args)))in before.entities.iter().zip(&after.entities).enumerate(){tick().map_err(err)?;if old_name!=name{return Err(err("ifc-domain-type-draft-required"));}let declaration=catalog::ifc2x3_catalog().entities.get(&name.to_ascii_uppercase()).ok_or_else(||err("ifc-domain-entity"))?;let attributes=if after.entities.len()==1{&declaration.all_attributes}else{&declaration.attributes};if args.len()<prior.len()&&args.len()<attributes.len(){return Err(err("ifc-domain-argument-arity"));}
 for(index,next)in args.iter().enumerate(){tick().map_err(err)?;let previous=prior.get(index);if let Some(previous)=previous{if domain::identical(previous,next,tick).map_err(err)?{continue;}}let attribute=attributes.get(index).ok_or_else(||err("ifc-domain-attribute"))?;if attribute.derived||after.entities.iter().filter_map(|(name,_)|catalog::ifc2x3_catalog().entities.get(&name.to_ascii_uppercase())).any(|declaration|declaration.all_attributes.iter().any(|other|other.derived&&other.name==attribute.name&&other.declared_by==attribute.declared_by)){return Err(err("ifc-domain-derived"));}
 let mut reference=|id:u64,expected:&str,tick:&mut dyn FnMut()->Result<(),String>|{let mut count=0;let mut accepted=false;for target in &snapshot.document.instances{tick()?;if target.id==id{count+=1;for(name,_)in &target.entities{tick()?;accepted|=catalog::ifc2x3_is_subtype(name,expected);}}}Ok(count==1&&accepted)};let mut control=DomainControl{tick,reference:&mut reference};
 if let Some(previous)=previous{let prefix=format!("/document/instances/{row}/entities/{part}/arguments/{index}");let suffix=path.strip_prefix(&prefix).filter(|suffix|suffix.is_empty()||suffix.starts_with('/'));let mut indices=[0;128];let length=if let Some(suffix)=suffix{route(previous,suffix,&mut indices).map_err(err)?}else{0};domain::check_change(catalog::ifc2x3_catalog(),&attribute.type_expr,previous,next,&indices[..length],operation,attribute.optional,&mut control).map_err(err)?;}else{domain::check_value(catalog::ifc2x3_catalog(),&attribute.type_expr,next,attribute.optional,true,&mut control).map_err(err)?;}
 }}}
 Ok(())
}

impl super::domain_cursor::DomainPopulation for Ifc2x3Snapshot{fn len(&self)->usize{self.document.instances.len()}fn id(&self,row:usize)->u64{self.document.instances[row].id}fn constituent_count(&self,row:usize)->usize{self.document.instances[row].entities.len()}fn constituent_name(&self,row:usize,part:usize)->&str{&self.document.instances[row].entities[part].0}}
